.drawer label { display: flex; flex-direction: column; gap: 0.25rem; font-size: 0.85rem; color: var(--text-dim); }
.drawer select, .drawer input {
  font: inherit;
  color: var(--text);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0.35rem;
}
.dial { display: flex; align-items: center; gap: 0.5rem; font-size: 0.85rem; color: var(--text-dim); }
.badge { font-size: 0.8rem; color: var(--text-dim); }
.debug { font-family: ui-monospace, Consolas, monospace; font-size: 0.8rem; }
.debug dt { color: var(--text-dim); }
.debug dd { margin: 0 0 0.4rem; }
.progress { width: 100%; }

