// Minimal IndexedDB key-value wrapper (stand-in for idb-keyval; no dependency).

const DB_NAME = "localghost";
const STORE = "kv";

let dbPromise: Promise<IDBDatabase> | null = null;

function openDb(): Promise<IDBDatabase> {
  if (!dbPromise) {
    dbPromise = new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = () => req.result.createObjectStore(STORE);
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => {
        dbPromise = null;
        reject(req.error);
      };
    });
  }
  return dbPromise;
}

async function run<T>(mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const req = fn(db.transaction(STORE, mode).objectStore(STORE));
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export const idbGet = <T>(key: string) => run<T | undefined>("readonly", (s) => s.get(key));
export const idbSet = async (key: string, value: unknown) => void (await run("readwrite", (s) => s.put(value, key)));
export const idbDel = async (key: string) => void (await run("readwrite", (s) => s.delete(key)));
export const idbKeys = () => run<IDBValidKey[]>("readonly", (s) => s.getAllKeys());
export const idbClear = async () => void (await run("readwrite", (s) => s.clear()));

// Records named timings and counters for the DebugPanel and the write-up.

export interface TimingEntry {
  label: string;
  ms: number;
}

type Listener = () => void;

const entries: TimingEntry[] = [];
const counters = new Map<string, number>();
const listeners = new Set<Listener>();
let version = 0;

function emit() {
  version++;
  listeners.forEach((l) => l());
}

export const timing = {
  record(label: string, ms: number) {
    entries.push({ label, ms });
    emit();
  },
  /** Start a timer; call the returned function to record and get elapsed ms. */
  start(label: string): () => number {
    const t0 = performance.now();
    return () => {
      const ms = performance.now() - t0;
      timing.record(label, ms);
      return ms;
    };
  },
  count(name: string, by = 1) {
    counters.set(name, (counters.get(name) ?? 0) + by);
    emit();
  },
  entries: (): readonly TimingEntry[] => entries,
  counters: (): ReadonlyMap<string, number> => counters,
  reset() {
    entries.length = 0;
    counters.clear();
    emit();
  },
  subscribe(l: Listener) {
    listeners.add(l);
    return () => void listeners.delete(l);
  },
  /** Snapshot token for useSyncExternalStore. */
  version: () => version,
};

// Parser for OpenAI-style server-sent events. Feed raw text chunks; get `data:` payloads.
// "[DONE]" is surfaced as `done: true`.

export interface SseResult {
  data: string[];
  done: boolean;
}

export class SseParser {
  private buf = "";

  push(chunk: string): SseResult {
    this.buf += chunk;
    const lines = this.buf.split(/\r\n|\n|\r/);
    this.buf = lines.pop() ?? "";
    return this.consume(lines);
  }

  /** Flush a trailing line that had no newline terminator. */
  flush(): SseResult {
    const rest = this.buf;
    this.buf = "";
    return this.consume(rest ? [rest] : []);
  }

  private consume(lines: string[]): SseResult {
    const data: string[] = [];
    let done = false;
    for (const line of lines) {
      if (!line.startsWith("data:")) continue; // comments, event:, blank lines
      const payload = line.slice(5).trim();
      if (payload === "[DONE]") done = true;
      else if (payload) data.push(payload);
    }
    return { data, done };
  }
}

import { describe, expect, it } from "vitest";
import { SseParser } from "./sse";

describe("SseParser", () => {
  it("parses data lines and DONE", () => {
    const p = new SseParser();
    const r = p.push('data: {"a":1}\n\ndata: {"a":2}\n\ndata: [DONE]\n\n');
    expect(r.data).toEqual(['{"a":1}', '{"a":2}']);
    expect(r.done).toBe(true);
  });
  it("handles chunks split mid-line", () => {
    const p = new SseParser();
    expect(p.push('data: {"a"').data).toEqual([]);
    expect(p.push(":1}\n").data).toEqual(['{"a":1}']);
  });
  it("ignores comments and flushes trailing line", () => {
    const p = new SseParser();
    expect(p.push(": keepalive\ndata: x").data).toEqual([]);
    expect(p.flush().data).toEqual(["x"]);
  });
});

