          <div className="hint">The Stage. Nothing is summoned yet.</div>
        </main>
        <aside className="drawer">
          <div className="tabs">
            {(["settings", "memories", "debug"] as const).map((t) => (
              <button key={t} className={tab === t ? "active" : ""} onClick={() => setTab(t)}>
                {t}
              </button>
            ))}
          </div>
          <div className="panel">{tab}</div>
        </aside>
      </div>
    </div>
  );
}
